import{_ as t,o as n,c as a,ak as o}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy current decisions","description":"Game design · Lesson sources · Execution","frontmatter":{"title":"Chainy current decisions","description":"Game design · Lesson sources · Execution","source":"docs/project-baseline.md","category":"Start here","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/project-baseline.md","filePath":"content/docs/project-baseline.md"}'),i={name:"content/docs/project-baseline.md"};function r(s,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-current-decisions">Chainy current decisions<a class="header-anchor" href="#chainy-current-decisions" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/planning/a-z-complete-lesson-quiz-source-draft.html">Lesson sources</a> · <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">Execution</a></p><p><strong>Chainy is an offline Android 3D exploration and lesson-collection game.</strong> The owner confirmed the gameplay direction below on November 11, 2026. <strong>Current authorization is documentation and necessary preparation only.</strong> Unity development, scene changes, gameplay code, and implementation agents must wait for the owner&#39;s explicit final decision. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> is the current gameplay specification. It supersedes the economy, lantern purchase, restoration, and actual-model-training requirements. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/project-baseline.html">previous baseline</a> preserves earlier decisions and local edits.</p><h2 id="confirmed-gameplay">Confirmed gameplay<a class="header-anchor" href="#confirmed-gameplay" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Area</th><th>Current requirement</th></tr></thead><tbody><tr><td>Journey</td><td>Main menu, world selection, 3D island, tutorial NPC, ordered lessons, required review quiz</td></tr><tr><td>Worlds</td><td>Web3, then Blockchain, then AI; complete the required quiz to unlock the next world</td></tr><tr><td>Curriculum</td><td>13 individual lessons per world, 39 total, in prerequisite order chosen for this design</td></tr><tr><td>Collection</td><td>Ordinary lessons use island objects; completion records their entries in the encyclopedia</td></tr><tr><td>Minigames</td><td>Three distinct minigames per world, nine total; separate scenes with ordered item, NPC, and facility prerequisites</td></tr><tr><td>Controls</td><td>Mobile joystick and interaction buttons; encyclopedia, linear quest log, pause</td></tr><tr><td>AI</td><td>Clearly labeled offline teaching simulation is acceptable; actual model training is not required</td></tr><tr><td>Economy</td><td>No earning, balances, purchases, trading, reward currency, or restoration loop</td></tr><tr><td>Connectivity</td><td>Offline gameplay; no real wallet, blockchain transaction, cloud model, or multiplayer requirement</td></tr><tr><td>Storage</td><td>SQLite locally; related progress must commit before completion appears</td></tr></tbody></table><p>The GDD specifies all nine activity rules, 39 draft lesson panels, and 39 draft questions. The owner confirmed 13 required quiz questions per world, one per lesson, with retries until all mistakes are corrected. Separate first-response scores, safe return points, and locked-entry presentation are specified design defaults for review. Educator review and learner testing remain distinct from writing this content.</p><h2 id="current-implementation-evidence">Current implementation evidence<a class="header-anchor" href="#current-implementation-evidence" aria-label="Link to this section">​</a></h2><p>The active game checkout is <code>O:/Documents/Unity Projects/ChainyApp</code>, using Unity 6000.3.25f1 and Plastic SCM. The November 11 audit found changeset 185, with existing SQLite, profile, encyclopedia, quest UI, movement, dialogue, and Wordle code. Before new implementation, all 57 existing Wordle EditMode tests passed. This proves those checks only, not Android acceptance. Android Build Support was missing at audit. An installation was started prematurely and cancelled when the owner clarified the documentation-only boundary; toolchain readiness is not established. The old standalone .NET test command could not run because the SDK and referenced project files were absent; Unity Test Framework is available.</p><p>The owner wants a complete design, clear documentation, and a prepared parallel workflow before deciding when development begins. The earlier execution directive is superseded by the explicit instruction to await final approval. Prepare the dependency graph, interface proposals, file boundaries, and verification criteria now; do not execute the implementation packets. Future agent work will not depend on assumed human availability. Builds, runtime checks, device performance, and evidence must be reported separately when development is authorized.</p><h2 id="retained-constraints">Retained constraints<a class="header-anchor" href="#retained-constraints" aria-label="Link to this section">​</a></h2><p>The game targets ages 12–17, initially in English, and communities with limited connectivity. The isometric camera, low-poly direction, Explorer character, and robot guides remain reusable. Guide names remain Sean for Web3, Matthew for Blockchain, and Lee for AI. SQLite remains the local store; JSON may be used for authored content or export, not as a replacement save store. Local demo profiles do not authenticate enrollment or recover another phone&#39;s data. Participant identities, credentials, and signing keys stay out of repositories and issues.</p><p>The minimum install setting remains API 25. Reference-device acceptance remains Android 10/API 29, 4 GB physical RAM, 128 GB total storage, and a reported 2.3 GHz octa-core processor, labeled &quot;vivo 2019&quot; in supplied evidence. That label does not establish a retail model, GPU, or ABI. A named APK must pass <a href="/Chainy-Docs/content/docs/hardware-validation.html">hardware validation</a> on the reference phone; desktop tests do not establish device performance.</p><p><strong>Pre-final remains November 21, 2026.</strong> The actual outcome of the November 10 Cryptita Plays session is not established by this audit. Do not invent beta results, pilot permissions, school acceptance, or the school&#39;s completion calculation. Preserve integration, QA, manuscript, and rehearsal evidence.</p><h2 id="ownership-and-management">Ownership and management<a class="header-anchor" href="#ownership-and-management" aria-label="Link to this section">​</a></h2><p>Human board ownership remains Sherwin for coordination/design, Christian for code/data/builds, Luis for art, Sean for authored documentation, and Miguel for UI. Autonomous agents execute work without becoming board accounts or erasing those responsibilities. Use the team board for card edits and named history; GitHub issues are queued copies and <code>backlog.json</code> is a publication snapshot. Preserve completed work and reconcile superseded economy cards through the board. Teacher services, vouchers, dashboards, exports, and standalone Wordle/BlockMatch are outside the current scope and should be archived with their history. Unfinished board work is to be rebaselined after the documentation review; dated planning targets do not authorize development. The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#12-design-acceptance-cases">GDD acceptance cases</a> govern current gameplay checks; historical V2-R and GP IDs retain their original meanings.</p></div>',1)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
